		}

		return retval;
	},

	async verifyModifiableLots() {
    const rows = (tblLots.selectedRows || []).filter(r => r && r.nocopk != null);
    if (!rows.length) {
			showAlert("No lots selected", 'error');
      await storeValue('lots_error', "No lots selected");			
			return false;
		}	

		let retval = true;
		for (const v of rows) {
			if ( v.item_category_mat !== 'fruiting_block') {
				showAlert(v.lot_id + " must be a fruiting block to modify.", 'error');
				retval = false;
			}

			if ( v.status.includes("Consumed") || v.status.includes("Expired") || v.status.includes("Retired") || v.status.includes("Compose") || v.status.includes("Composted")  ) {
				showAlert(v.lot_id + " is already retired (" + v.status + ")", 'error');
				retval = false;
			}

		}		
		return retval;
	},

	async verifyMoveableLots() {
    const rows = (tblLots.selectedRows || []).filter(r => r && r.nocopk != null);
    if (!rows.length) {
			showAlert("No lots selected", 'error');
      await storeValue('lots_error', "No lots selected");			
			return false;
		}	

		let retval = true;
		for (const v of rows) {
			if (! ( v.inoculated_at || v.spawned_at ) )  {
				showAlert(v.lot_id + " must be inoculated or spawned to transition.", 'error');
				retval = false;
			}

			if ( v.status.includes("Consumed") || v.status.includes("Expired") || v.status.includes("Retired") || v.status.includes("Compose") || v.status.includes("Composted")  ) {
				showAlert(v.lot_id + " is already retired (" + v.status + ")", 'error');
				retval = false;
			}

			//showAlert("Querying " + v.location_id, "notice");
			const location = await qLocationByID.run({
        location_id: v.location_id
      });
			//showAlert("Got " + location[0]?.name, "notice");		

			if(location[0]?.name.includes("Fruiting")) {
				showAlert(v.lot_id + " is already located in: " + location[0].name, 'error');
				retval = false;
			}

		}

		return retval;
	},

	async verifyRetireableLots() {
    const rows = (tblLots.selectedRows || []).filter(r => r && r.nocopk != null);
    if (!rows.length) {
			showAlert("No lots selected", 'error');
      await storeValue('lots_error', "No lots selected");			
			return false;
		}	

		let retval = true;
		for (const v of rows) {
			if ( v.status.includes("Consumed") || v.status.includes("Expired") || v.status.includes("Retired") || v.status.includes("Compose") || v.status.includes("Composted")  ) {
				showAlert(v.lot_id + " is already retired (" + v.status + ")", 'error');
				retval = false;
			}
		}

		return retval;
	},	

	async verifyPackageableLots() {
    const rows = (tblLots.selectedRows || []).filter(r => r && r.nocopk != null);
    if (!rows.length) {
			showAlert("No lots selected", 'error');
      await storeValue('lots_error', "No lots selected");			
			return false;
		}	

		let retval = true;
		for (const v of rows) {
			//Row by row validation
			if ( v.status.includes("Consumed") || v.status.includes("Expired") || v.status.includes("Retired") || v.status.includes("Compose") || v.status.includes("Composted")  ) {
				showAlert(v.lot_id + " is already retired (" + v.status + ")", 'error');
				retval = false;
			}
		}

		return retval;
	},	

	async verifyInoculateLots() {
    const rows = (tblLots.selectedRows || []).filter(r => r && r.nocopk != null);
    if (!rows.length) {
			showAlert("No lots selected", 'error');
      await storeValue('lots_error', "No lots selected");			
			return false;
		}	

		let retval = true;
		for (const v of rows) {
			//Row by row validation
			if (! ( v.item_category_mat == 'grain' || v.item_category_mat == 'lc_flask' || v.item_category_mat == 'plate' ) ) {
				showAlert(v.lot_id + " must be  a grain, flask or plate to inoculate.", 'error');
				retval = false;
			}

		}

		return retval;
	},	

  async openShakeModal() {
    if (!this.selectedLotIds().length) return showAlert("Select one or more lots first.", "warning");
		if (!await this.verifyShakeableLots()) return showAlert("Select shakeable lots to shake.", "warning");
    txtShakeContent.setText(this.formatSelectedLots());
    await showModal(modalShakeLots.name);
  },

  async openRetireModal() {
    if (!this.selectedLotIds().length) return showAlert("Select one or more lots first.", "warning");
		if (!await this.verifyRetireableLots()) return showAlert("Select retireable lots to retire.", "warning");
    txtRetireContent.setText(this.formatSelectedLots());
    await showModal(modalRetireLots.name);
  },

  async openModifyModal() {
    if (!this.selectedLotIds().length) return showAlert("Select one or more lots first.", "warning");
		if (!await this.verifyModifiableLots()) return showAlert("Select only modifiable fruiting blocks.", "warning");
    txtModifyContent.setText(this.formatSelectedLots());
    await showModal(modalModifyLots.name);
  },	

  async openMoveModal() {
    if (!this.selectedLotIds().length) return showAlert("Select one or more lots first.", "warning");
		if (!await this.verifyMoveableLots()) return showAlert("Select moveable lots to transition.", "warning");
    txtMoveContent.setText(this.formatSelectedLots());
    await showModal(modalMoveLots.name);
  },	

  async openPackageModal() {
    if (!this.selectedLotIds().length) return showAlert("Select one or more lots first.", "warning");
		//if (!await this.verifyPackageableLots()) return showAlert("Select valid lots to package.", "warning");

		txtPackageContent.setText(this.formatSelectedLots());

		// Refresh source lots list + locations
    Promise.allSettled([qProductLocations.run()]).finally(() => {
      showModal(modalPackageLots.name);
    });
  },	

  selectedLotsSummary() {
    const rows = (tblLots.selectedRows || []).filter(r => r && r.nocopk != null);
    if (!rows.length) return "No lots selected.";
    return rows.map(r => {
      const lot = r.lot_id || r.lotId || r.lot_id_mat || r.nocopk;
      const inoc = r.inoculated_at || r.inoculatedAt || r.created_at || r.createdAt || "";
      const item = r.item_name_mat || r.item_name || r.itemName || "";
      const strain = r.strain_species_strain_mat || r.strain_species_strain || r.species_strain || "";
      return `${lot} | inoculated: ${inoc || "—"} | ${item} | ${strain}`;
    }).join("\n");
  },

  async shakeSelectedLots() {

		if (!this.selectedLotIds().length) return showAlert("Select one or more lots first.", "warning");

		let lotsshaken;
    try {
      lotsshaken = await qShakeLots.run();
      // refresh downstream view
    } catch (e) {
			showAlert("Error flagging lots as shaken: " + (e && e.message) ? e.message : String(e), 'error');
      await storeValue('lots_error', (e && e.message) ? e.message : String(e));
			return;
    }		

		showAlert("Shook " + lotsshaken[0].shaken_count + " lot(s).", 'success');

		txtShakeContent.setText("");
		inpShakeNotes.setValue("");		
    closeModal(modalShakeLots.name);
    await qLots.run();
  },

  async retireSelectedLots() {

		if (!this.selectedLotIds().length) return showAlert("Select one or more lots first.", "warning");

		let lotsretired;
    try {
      lotsretired = await qRetireLots.run();
      // refresh downstream view
    } catch (e) {
			showAlert("Error retiring lots: " + (e && e.message) ? e.message : String(e), 'error');
      await storeValue('lots_error', (e && e.message) ? e.message : String(e));
			return;
    }	

		showAlert("Retired " + lotsretired[0].retired_count + " lot(s).", 'success');

		txtRetireContent.setText("");
		inpRetireNotes.setValue("");		
    closeModal(modalRetireLots.name);
    await qLots.run();
  },

  async moveSelectedLots() {

		if (!this.selectedLotIds().length) return showAlert("Select one or more lots first.", "warning");

		let lotsmoved;
    try {
      lotsmoved = await qMoveLots.run();
      // refresh downstream view
    } catch (e) {
			showAlert("Error moving lots: " + (e && e.message) ? e.message : String(e), 'error');
      await storeValue('lots_error', (e && e.message) ? e.message : String(e));
			return;
    }	

		showAlert("Moved " + lotsmoved[0].moved_count + " lot(s).", 'success');

		txtMoveContent.setText("");
		inpMoveNotes.setValue("");		
    closeModal(modalMoveLots.name);
    await qLots.run();
  },	

  async modifySelectedLots() {

		if (!this.selectedLotIds().length) return showAlert("Select one or more lots first.", "warning");

		let lotsmodified;
    try {
      lotsmodified = await qModifyLots.run();
      // refresh downstream view
    } catch (e) {
			showAlert("Error modifying lots: " + (e && e.message) ? e.message : String(e), 'error');
      await storeValue('lots_error', (e && e.message) ? e.message : String(e));
			return;
    }		

		showAlert("Modified " + lotsmodified[0].modified_count + " lot(s).", 'success');

		txtModifyContent.setText("");
		inpModifyNotes.setValue("");		
    closeModal(modalModifyLots.name);
    await qLots.run();
  },	

  async packageSelectedLots() {

		if (!this.selectedLotIds().length) return showAlert("Select one or more lots first.", "warning");

		let lotspackaged;
    try {
      lotspackaged = await qPackageLots.run();
      // refresh downstream view
    } catch (e) {
			showAlert("Error packaging lots: " + (e && e.message) ? e.message : String(e), 'error');
      await storeValue('lots_error', (e && e.message) ? e.message : String(e));
			return;
    }		

		showAlert("Packaged " + lotspackaged[0].packaged_count + " lot(s).", 'success');

		txtPackageContent.setText("");
		inpPackageNotes.setValue("");		
    closeModal(modalPackageLots.name);
    await qLots.run();
  },		

  async openInoculateModal() {
    // Requires at least one target lot selected in tblLots
    const ids = this.selectedLotIds();
    if (!ids.length) {
      showAlert('Select one or more TARGET lots in the Lots table first.', 'warning');
      return;
    }

		//if (!await this.verifyInoculateLots()) return showAlert("Select valid lots to package.", "warning");

		txtInoculateContent.setText(this.formatSelectedLots());

    // Refresh source lots list + locations
    Promise.allSettled([qSourceLotsSearch.run(), qInocLocations.run()]).finally(() => {
      showModal(modalInoculateLots.name);
    });
  },

  async inoculateSelectedLots() {
    const targetIds = this.selectedLotIds();
    if (!targetIds.length) {
      showAlert('No target lots selected.', 'warning');
      return;
    }

    const src = tblInocSourceLots.selectedRow;
    const sourceId = src?.nocopk;
    if (!sourceId) {
      showAlert('Select a SOURCE lot in the Source Lots table.', 'warning');
      return;
    }

    // Inputs from modal
    const lcVol = Number(inpInocLCVolML.text);
    const storageLoc = selInoculateLocation.selectedOptionValue || 'Dark Room';
    const overrideTime = dpInoculateOverrideTime.selectedDate || null;
    const notes = inpInoculateNotes.text || '';

    // Stash for query templating
    await storeValue('inoc_source_id', sourceId);
    await storeValue('inoc_target_ids', targetIds);
    await storeValue('inoc_lc_vol', Number.isFinite(lcVol) ? lcVol : null);
    await storeValue('inoc_storage_loc', storageLoc);
    await storeValue('inoc_override_time', overrideTime);
    await storeValue('inoc_note', notes);

    try {
      const inoculated = await qInoculateLots.run();
      closeModal(modalInoculateLots.name);
      await this.refresh();
      showAlert('Inoculation of ' + inoculated.length + ' lot(s) complete.', 'success');
    } catch (e) {
      // Surface server-side validation errors on the source lot where possible.
      showAlert(e?.message || 'Inoculation failed.', 'error');
    }
  },

  async openDrawSyringesModal() {
    const rows = (tblLots.selectedRows || []);
    if (rows.length !== 1 || rows[0].item_category_mat !== 'lc_flask') {
      showAlert('Select exactly one lc_flask lot first.', 'warning');
      return;
    }

    inpSyringeCount.setValue('1');
    inpSyringeMlEach.setValue('10');
    inpDrawSyringesNotes.setValue('');
    await showModal(modalDrawSyringes.name);
  },

  async drawSyringesFromSelectedFlask() {
    const rows = (tblLots.selectedRows || []);
    if (rows.length !== 1 || rows[0].item_category_mat !== 'lc_flask') {
      showAlert('Select exactly one lc_flask lot first.', 'warning');
      return;
    }

    const count = Number(inpSyringeCount.text);
    const mlEach = Number(inpSyringeMlEach.text);
    if (!Number.isFinite(count) || count <= 0) {
      showAlert('Enter a syringe count greater than 0.', 'warning');
      return;
    }
    if (!Number.isFinite(mlEach) || mlEach <= 0) {
      showAlert('Enter mL per syringe greater than 0.', 'warning');
      return;
    }

    try {
      const res = await qDrawSyringes.run();
      showAlert('Syringe lots created.', 'success');
      closeModal(modalDrawSyringes.name);
      await this.refresh();
      return res;
    } catch (e) {
      showAlert(e?.message || String(e), 'error');
      return null;
    }
  },

};

