export default {
  currentOperator() {
    const email = (appsmith.user?.email || "").trim().toLowerCase();
    const name = (appsmith.user?.name || "").trim();
    if (email) return email;
    if (name) return name;
    return "system";
  },

  sql: {
    str(v) {
      if (v === undefined || v === null || v === "") return "NULL";
      return "'" + String(v).replace(/'/g, "''") + "'";
    },
    num(v) {
      const n = Number(v);
      return Number.isFinite(n) ? String(n) : "NULL";
    },
    arrBigint(arr) {
      if (!arr || arr.length === 0) return "ARRAY[]::bigint[]";
      const vals = arr.map(x => {
        const n = Number(x);
        return Number.isFinite(n) ? String(n) : "NULL";
      }).filter(x => x !== "NULL");
      if (vals.length === 0) return "ARRAY[]::bigint[]";
      return "ARRAY[" + vals.join(", ") + "]::bigint[]";
    },
  },

  parseLinkedProductsFromSelectedOrder() {
    const row = tblFulfillmentOrders.selectedRow || {};

    const ids = String(row.product_ids_report || "")
      .split(",")
      .map(s => s.trim())
      .filter(Boolean);

    const names = String(row.products_report || "")
      .split(",")
      .map(s => s.trim())
      .filter(Boolean);

    const count = Math.max(ids.length, names.length);

    return Array.from({ length: count }, (_, i) => ({
      line_index: i + 1,
      product_id: ids[i] || "",
      name_mat: names[i] || "",
    }));
  },

  async clearSelectionState() {
    await storeValue("fulfillment_selected_order_id", "");
    await storeValue("fulfillment_order_detail", null);
    await storeValue("fulfillment_product_results", []);
    await storeValue("fulfillment_linked_products", []);
  },

  async syncLinkedProductsFromSelectedOrder() {
    const linked = this.parseLinkedProductsFromSelectedOrder();
    await storeValue("fulfillment_linked_products", linked);
    return linked;
  },

  async loadOrders() {
    const res = await apiFulfillmentListOrders.run();

    if (!res || res.ok === false) {
      showAlert((res && res.error) || "Could not load fulfillment orders", "error");
      return res;
    }

    const selectedId = appsmith.store.fulfillment_selected_order_id || "";
    const orders = res.orders || [];
    const stillExists = !!selectedId && orders.some(o => o.airtable_record_id === selectedId);

    if (!stillExists) {
      await this.clearSelectionState();
    } else {
      await this.syncLinkedProductsFromSelectedOrder();
    }

    return res;
  },

  async handleOrderSelected() {
    const orderId = tblFulfillmentOrders.selectedRow?.airtable_record_id || "";

    await storeValue("fulfillment_selected_order_id", orderId);
    await this.syncLinkedProductsFromSelectedOrder();

    const detailRes = await apiFulfillmentOrderDetail.run();

    if (!detailRes || detailRes.ok === false) {
      await storeValue("fulfillment_order_detail", null);
      showAlert((detailRes && detailRes.error) || "Could not load order detail", "error");
      return detailRes;
    }

    await storeValue("fulfillment_order_detail", detailRes);

    const productRes = await apiFulfillmentProductSearch.run();

    if (!productRes || productRes.ok === false) {
      await storeValue("fulfillment_product_results", []);
      showAlert((productRes && productRes.error) || "Product search failed", "error");
      return detailRes;
    }

    await storeValue("fulfillment_product_results", productRes.products || []);
    return detailRes;
  },

  async reloadOrderDetail() {
    await this.syncLinkedProductsFromSelectedOrder();

    const detailRes = await apiFulfillmentOrderDetail.run();

    if (!detailRes || detailRes.ok === false) {
      await storeValue("fulfillment_order_detail", null);
      showAlert((detailRes && detailRes.error) || "Could not load order detail", "error");
      return detailRes;
    }

    await storeValue("fulfillment_order_detail", detailRes);

    const productRes = await apiFulfillmentProductSearch.run();

    if (!productRes || productRes.ok === false) {
      await storeValue("fulfillment_product_results", []);
      showAlert((productRes && productRes.error) || "Product search failed", "error");
      return detailRes;
    }

    await storeValue("fulfillment_product_results", productRes.products || []);
    return detailRes;
  },

  async searchProducts() {
    const res = await apiFulfillmentProductSearch.run();

    if (!res || res.ok === false) {
      await storeValue("fulfillment_product_results", []);
      showAlert((res && res.error) || "Product search failed", "error");
      return res;
    }

    await storeValue("fulfillment_product_results", res.products || []);
    return res;
  },

  async assignSelectedProduct() {
    const res = await apiFulfillmentAssignProduct.run();

