function () {
  const row = tblFulfillmentOrders.selectedRow || ({});
  const ids = String(row.product_ids_report || "").split(",").map(s => s.trim()).filter(Boolean);
  const names = String(row.products_report || "").split(",").map(s => s.trim()).filter(Boolean);
  const count = Math.max(ids.length, names.length);
  return Array.from({
    length: count
  }, (_, i) => ({
    line_index: i + 1,
    product_id: ids[i] || "",
    name_mat: names[i] || ""
  }));
}

